"""The recurring presenter: a single, replaceable, procedural vector rig.

Design goals
  * **One identity everywhere.**  The character is *drawn*, never generated by a
    model, so head shape, hair, scarf, proportions and palette are identical in
    every scene, format and language.
  * **Smooth vector look.**  Every part is an anti-aliased shape with a vertical
    shading ramp, a soft silhouette line and a rim light from the key light, so
    the presenter sits in the same graphic language as the type and diagrams
    (no pixel blocks, no sprite upscaling artefacts).
  * **Poses, not new art.**  Poses/gestures are parameters (arm angles, lean,
    head tilt, mouth, blink, bounce), so the presenter can point at a prop,
    react to a beat or hold a board without new assets.
  * **Replaceable.**  `CHARACTER_SPEC` holds all proportions and colours.  Swap
    the spec (or subclass) to install an approved design; nothing else changes.

Original design (not derived from any existing character): "Nami", a presenter
in a cream shirt, indigo overalls, an orange scarf and a dark-teal bob.

How a sprite is built
  1. every body part is drawn flat, in painting order, into one RGBA layer;
  2. the layer is multiplied by a vertical shading ramp (light from above);
  3. the silhouette's alpha is dilated and drawn underneath as the line colour;
  4. a rim-light band is cut from the silhouette's light-facing edge;
  5. face, seams and highlights are drawn on top, crisp.
The whole sprite is cached per (pose, blink, mouth, tilt, facing, holding).
"""
from __future__ import annotations

import math
from dataclasses import dataclass, replace
from typing import Dict, Optional, Tuple

from PIL import Image, ImageChops, ImageDraw, ImageFilter

# logical design canvas (units); the rig is drawn at SUPERSAMPLE x this size
BASE_W = 120.0
BASE_H = 176.0
FEET_Y = 172.0
SUPERSAMPLE = 4

RGB = Tuple[int, int, int]


@dataclass(frozen=True)
class CharacterSpec:
    # --- line / light -------------------------------------------------------
    line: RGB = (34, 26, 44)
    line_alpha: int = 235
    rim: RGB = (255, 233, 197)
    # --- skin ---------------------------------------------------------------
    skin: RGB = (246, 202, 168)
    skin_shade: RGB = (226, 166, 130)
    blush: RGB = (240, 140, 128)
    # --- hair ---------------------------------------------------------------
    hair: RGB = (38, 58, 74)
    hair_light: RGB = (62, 90, 112)
    # --- clothes ------------------------------------------------------------
    shirt: RGB = (255, 243, 220)
    shirt_shade: RGB = (232, 210, 180)
    overalls: RGB = (62, 92, 158)
    overalls_dark: RGB = (44, 66, 116)
    accent: RGB = (255, 138, 76)
    accent_dark: RGB = (214, 96, 48)
    boots: RGB = (44, 38, 56)
    # --- face ---------------------------------------------------------------
    eye: RGB = (36, 32, 46)
    white: RGB = (255, 255, 255)


CHARACTER_SPEC = CharacterSpec()

# arm angles are degrees: 0 = straight down, 90 = out to the character's right,
# 180 = straight up.  `elbow` bends the forearm relative to the upper arm.
POSES: Dict[str, Dict[str, float]] = {
    # arm_l, elbow_l, arm_r, elbow_r -- angles are outward magnitudes
    "idle":        {"arm_l": 10, "elbow_l": 12, "arm_r": 12, "elbow_r": 14},
    # both hands open at chest height, elbows down and out
    "present":     {"arm_l": 32, "elbow_l": 86, "arm_r": 30, "elbow_r": 84},
    # one hand out, the other folded: a talking gesture, never a T-pose
    "explain":     {"arm_l": 26, "elbow_l": 74, "arm_r": 16, "elbow_r": 22},
    "point_right": {"arm_l": 12, "elbow_l": 16, "arm_r": 38, "elbow_r": 56},
    "point_left":  {"arm_l": 38, "elbow_l": 56, "arm_r": 12, "elbow_r": 16},
    # elbow raised, forearm folded in so the hand lands near the chin
    "think":       {"arm_l": 12, "elbow_l": 18, "arm_r": 118, "elbow_r": 78},
    "celebrate":   {"arm_l": 145, "elbow_l": 26, "arm_r": 148, "elbow_r": 22},
    # palms up, shoulders lifted
    "shrug":       {"arm_l": 60, "elbow_l": 62, "arm_r": 58, "elbow_r": 64},
}


# --------------------------------------------------------------------- helpers
def _rgba(color: RGB, alpha: int = 255) -> Tuple[int, int, int, int]:
    return (color[0], color[1], color[2], alpha)


def _shine(color: RGB, f: float) -> RGB:
    return tuple(max(0, min(255, int(c * f))) for c in color)  # type: ignore[return-value]


def _mix(a: RGB, b: RGB, t: float) -> RGB:
    return tuple(int(a[i] + (b[i] - a[i]) * t) for i in range(3))  # type: ignore[return-value]


def _vertical_ramp(size: Tuple[int, int], top: float, bottom: float) -> Image.Image:
    """L-mode ramp: `top` grey at the top edge, `bottom` grey at the bottom."""
    w, h = size
    grad = Image.linear_gradient("L").resize((w, h), Image.BILINEAR)
    # linear_gradient runs 0 (top) -> 255 (bottom); remap to our factors
    return grad.point(lambda v: int(top + (bottom - top) * (v / 255.0)))


def _shadowed(body: Image.Image, top: float = 255, bottom: float = 198) -> Image.Image:
    """Multiply an RGBA layer by a vertical light ramp, preserving alpha."""
    ramp = _vertical_ramp(body.size, top, bottom)
    rgb = body.convert("RGB")
    r, g, b = rgb.split()
    shaded = Image.merge("RGB", (ImageChops.multiply(r, ramp),
                                 ImageChops.multiply(g, ramp),
                                 ImageChops.multiply(b, ramp)))
    out = shaded.convert("RGBA")
    out.putalpha(body.getchannel("A"))
    return out


def _dilate(mask: Image.Image, px: int) -> Image.Image:
    if px <= 0:
        return mask
    return mask.filter(ImageFilter.MaxFilter(px * 2 + 1))


def _overlay(base: Image.Image, bbox, fn) -> None:
    """Draw onto `base` through a scratch layer.

    `ImageDraw` writes RGBA values verbatim instead of blending them, so a
    translucent fill (blush, glints, shading) would otherwise *replace* the pixel
    and punch a hole through the character.
    """
    x0, y0, x1, y1 = (int(bbox[0]), int(bbox[1]), int(bbox[2]), int(bbox[3]))
    x0, y0 = max(0, x0), max(0, y0)
    x1, y1 = min(base.width, x1), min(base.height, y1)
    if x1 <= x0 or y1 <= y0:
        return
    layer = Image.new("RGBA", (x1 - x0, y1 - y0), (0, 0, 0, 0))
    fn(ImageDraw.Draw(layer), x0, y0)
    base.alpha_composite(layer, (x0, y0))


def _capsule(d: ImageDraw.ImageDraw, p0, p1, width: float, color) -> None:
    d.line([p0, p1], fill=color, width=int(round(width)), joint="curve")
    r = width / 2.0
    for x, y in (p0, p1):
        d.ellipse((x - r, y - r, x + r, y + r), fill=color)


def _limb(
    shoulder: Tuple[float, float],
    angle: float,
    elbow: float,
    upper: float,
    fore: float,
) -> Tuple[Tuple[float, float], Tuple[float, float]]:
    a = math.radians(angle)
    ex = shoulder[0] + math.sin(a) * upper
    ey = shoulder[1] + math.cos(a) * upper
    b = math.radians(angle + elbow)
    hx = ex + math.sin(b) * fore
    hy = ey + math.cos(b) * fore
    return (ex, ey), (hx, hy)


class Character:
    """Vector rig.  One instance (`CHARACTER`) is shared by every scene."""

    def __init__(self, spec: CharacterSpec = CHARACTER_SPEC) -> None:
        self.spec = spec
        self._cache: Dict[tuple, Image.Image] = {}

    # ------------------------------------------------------------------ poses
    def pose(self, name: str) -> Dict[str, float]:
        return POSES.get(name, POSES["idle"])

    # ----------------------------------------------------------------- sprite
    def sprite(
        self,
        pose: str = "idle",
        *,
        blink: bool = False,
        mouth: str = "smile",
        tilt: float = 0.0,
        facing: int = 1,
        holding: Optional[str] = None,
    ) -> Image.Image:
        key = (pose, bool(blink), mouth, round(tilt, 1), 1 if facing >= 0 else -1, holding)
        cached = self._cache.get(key)
        if cached is not None:
            return cached
        img = self._build(self.pose(pose), blink=blink, mouth=mouth, tilt=tilt, holding=holding)
        if facing < 0:
            img = img.transpose(Image.FLIP_LEFT_RIGHT)
        if len(self._cache) > 64:
            self._cache.clear()
        self._cache[key] = img
        return img

    # ------------------------------------------------------------------- draw
    def draw(
        self,
        painter,
        x: float,
        y: float,
        height: float,
        pose: str = "idle",
        *,
        alpha: float = 1.0,
        blink: bool = False,
        mouth: str = "smile",
        bounce: float = 0.0,
        tilt: float = 0.0,
        facing: int = 1,
        holding: Optional[str] = None,
        shadow: bool = True,
        flip_180: bool = False,
    ) -> Tuple[float, float]:
        """Draw the character with its *feet* at (x, y) in layout pixels."""
        sprite = self.sprite(pose, blink=blink, mouth=mouth, tilt=tilt,
                             facing=facing, holding=holding)
        base_h = BASE_H * SUPERSAMPLE
        scale = height / BASE_H
        w = BASE_W * scale
        h = BASE_H * scale

        # ground contact shadow: a soft ellipse that agrees with the key light
        if shadow:
            sw, sh = w * 0.34, h * 0.030
            sx, sy = x - w * 0.02, y - sh * 0.55
            painter.ellipse(sx, sy, sw, sh, fill=(18, 12, 26, 52))
            painter.ellipse(sx, sy - sh * 0.16, sw * 0.74, sh * 0.72, fill=(18, 12, 26, 66))

        target = (max(1, int(round(w * painter.ss))), int(round(h * painter.ss)))
        cached_px = self._cache.get(("px", id(sprite), target))  # type: ignore[arg-type]
        if cached_px is None:
            cached_px = sprite.resize(target, Image.LANCZOS)
            if len(self._cache) > 96:
                self._cache.clear()
            self._cache[("px", id(sprite), target)] = cached_px  # type: ignore[index]
        painter.paste_sprite(cached_px, x - w / 2, y - h - bounce, scale=1.0, alpha=alpha)
        return w, h

    # ------------------------------------------------------------------ build
    def _build(self, p: Dict[str, float], *, blink: bool, mouth: str,
               tilt: float, holding: Optional[str]) -> Image.Image:
        s = self.spec
        S = SUPERSAMPLE
        size = (int(BASE_W * S), int(BASE_H * S))
        body = Image.new("RGBA", size, (0, 0, 0, 0))
        d = ImageDraw.Draw(body)

        def u(v: float) -> float:
            return v * S

        lean = float(p.get("lean", 0.0)) * 0.8
        cx = BASE_W / 2 + lean

        # ---------- skeleton (all lengths in design units) ----------
        head_cy = 48.0
        neck_top = 66.0
        shoulder_y = 82.0
        shoulder_half = 25.0
        waist_y = 112.0
        waist_half = 19.0
        hip_y = 122.0
        hip_half = 21.0
        foot_y = FEET_Y - 14.0

        def torso_path(half_sh: float, half_waist: float, half_hip: float):
            """Tapered shirt body: wide at the shoulders, narrow at the waist."""
            return [
                (cx - half_sh, shoulder_y + 6),
                (cx - half_sh + 1.5, shoulder_y - 3),
                (cx - 11, shoulder_y - 7),
                (cx + 11, shoulder_y - 7),
                (cx + half_sh - 1.5, shoulder_y - 3),
                (cx + half_sh, shoulder_y + 6),
                (cx + half_waist, waist_y),
                (cx + half_hip, hip_y + 2),
                (cx - half_hip, hip_y + 2),
                (cx - half_waist, waist_y),
            ]

        # ---------------------------------------------------------- legs
        for side in (-1, 1):
            lx = cx + side * 8.2
            trouser = _shine(s.overalls, 0.78)
            # each leg is its own shape with a real gap, so the silhouette reads
            # as two legs instead of one dark block
            d.rounded_rectangle((u(lx - 7.6), u(hip_y - 12), u(lx + 7.6), u(foot_y + 4)),
                                radius=u(6.0), fill=_rgba(trouser))
            # inner-edge shading, away from the key light
            inner0, inner1 = sorted((lx + side * 2.0, lx + side * 7.6))
            d.rounded_rectangle((u(inner0), u(hip_y - 6), u(inner1), u(foot_y + 2)),
                                radius=u(5.0), fill=_rgba(_shine(trouser, 1.12)))
            # rolled cuff
            d.rounded_rectangle((u(lx - 7.8), u(foot_y - 5), u(lx + 7.8), u(foot_y + 4)),
                                radius=u(3.0), fill=_rgba(_shine(trouser, 1.22)))
            # boot: sits just under the cuff, toe pointing outward
            bx0 = lx - 8.2 - (2.6 if side < 0 else 0.0)
            bx1 = lx + 8.2 + (2.6 if side > 0 else 0.0)
            d.rounded_rectangle((u(bx0), u(foot_y + 3), u(bx1), u(FEET_Y)),
                                radius=u(4.5), fill=_rgba(s.boots))
            d.rounded_rectangle((u(bx0 + 1.2), u(foot_y + 4.2), u(bx1 - 1.2), u(foot_y + 8.0)),
                                radius=u(2.2), fill=_rgba(_shine(s.boots, 1.65)))

        # ---------------------------------------------------------- back arm
        self._arm(d, s, u, shoulder=(cx + shoulder_half - 2.5, shoulder_y + 4.0),
                  angle=p["arm_r"], elbow=p["elbow_r"], side=1, back=True)

        # ---------------------------------------------------------- torso
        d.polygon([(u(x), u(y)) for x, y in torso_path(shoulder_half, waist_half, hip_half)],
                  fill=_rgba(s.shirt))
        # neck (in front of the torso top, behind the head)
        d.rounded_rectangle((u(cx - 7.0), u(neck_top - 4), u(cx + 7.0), u(shoulder_y + 2)),
                            radius=u(4.5), fill=_rgba(_shine(s.skin, 0.90)))

        # overalls: bib + hips, leaving shirt sleeves/collar visible
        bib = [(cx - 15.0, shoulder_y + 8), (cx + 15.0, shoulder_y + 8),
               (cx + 14.0, waist_y + 2), (cx - 14.0, waist_y + 2)]
        d.polygon([(u(x), u(y)) for x, y in bib], fill=_rgba(s.overalls))
        d.rounded_rectangle((u(cx - hip_half), u(waist_y - 2), u(cx + hip_half), u(hip_y + 2)),
                            radius=u(7), fill=_rgba(s.overalls))
        # shadow where the bib meets the trousers
        d.rounded_rectangle((u(cx - hip_half), u(waist_y - 3.5), u(cx + hip_half), u(waist_y + 1.5)),
                            radius=u(2.5), fill=_rgba(_shine(s.overalls, 0.78)))
        # waistband
        d.rounded_rectangle((u(cx - hip_half), u(waist_y - 3), u(cx + hip_half), u(waist_y + 4)),
                            radius=u(3), fill=_rgba(s.overalls_dark))
        # straps from the bib over the shoulders
        for sx in (cx - 15.0, cx + 10.5):
            d.rounded_rectangle((u(sx), u(shoulder_y - 6), u(sx + 4.5), u(shoulder_y + 12)),
                                radius=u(2.2), fill=_rgba(s.overalls))
        # collar: a shallow rounded V; a flat triangle reads as a notch in the torso
        d.ellipse((u(cx - 9.0), u(shoulder_y - 8.5), u(cx + 9.0), u(shoulder_y + 2.5)),
                  fill=_rgba(s.shirt_shade))
        d.ellipse((u(cx - 6.4), u(shoulder_y - 7.6), u(cx + 6.4), u(shoulder_y + 0.6)),
                  fill=_rgba(_shine(s.skin, 0.97)))

        # ---------------------------------------------------------- scarf
        # thin neckerchief: a band at the collar plus one hanging tail
        d.rounded_rectangle((u(cx - 9.5), u(shoulder_y - 7.5), u(cx + 9.5), u(shoulder_y - 1.5)),
                            radius=u(3.2), fill=_rgba(s.accent))
        d.polygon([(u(cx + 2.0), u(shoulder_y - 3.0)), (u(cx + 9.0), u(shoulder_y - 2.0)),
                   (u(cx + 6.5), u(shoulder_y + 13.0)), (u(cx + 1.5), u(shoulder_y + 11.0))],
                  fill=_rgba(s.accent_dark))

        # ---------------------------------------------------------- head
        tilt_v = max(-9.0, min(9.0, float(p.get("head", 0.0)) + tilt * 4.0))
        head_layer = self._head(s, u, blink=blink, mouth=mouth, tilt=tilt_v, head_cy=head_cy)
        body.alpha_composite(self._rotate(head_layer, tilt_v * 0.55, head_cy))

        # ---------------------------------------------------------- front arm
        self._arm(d, s, u, shoulder=(cx - shoulder_half + 2.5, shoulder_y + 4.0),
                  angle=p["arm_l"], elbow=p["elbow_l"], side=-1, back=False)
        if holding == "board":
            self._board(d, s, u, cx, shoulder_y)

        # ---------------------------------------------------- shading + line
        shaded = _shadowed(body, 255, 202)
        mask = shaded.getchannel("A")
        outline = Image.new("RGBA", size, _rgba(s.line, s.line_alpha))
        outline.putalpha(_dilate(mask, max(1, int(1.1 * S))))
        out = Image.alpha_composite(outline, shaded)

        # ------------------------------------------------------- rim light
        # A rim on *every* edge reads as a cream outline (very obvious under the
        # boots), so the light band is restricted to the top-left of the silhouette.
        rim_mask = ImageChops.subtract(mask, ImageChops.offset(mask, -int(2.0 * S), int(1.0 * S)))
        bottom_cut = ImageChops.subtract(mask, ImageChops.offset(mask, 0, int(1.2 * S)))
        rim_mask = ImageChops.subtract(rim_mask, ImageChops.offset(bottom_cut, 0, int(-1.0 * S)))
        rim_mask = rim_mask.filter(ImageFilter.GaussianBlur(0.6))
        rim = Image.new("RGBA", size, _rgba(s.rim, 110))
        rim.putalpha(rim_mask.point(lambda v: int(v * 0.42)))
        out = Image.alpha_composite(out, rim)

        # --------------------------------------------------------- details
        self._details(out, s, u, cx, shoulder_y, hip_y)
        return out

    # ------------------------------------------------------------------ parts
    def _head(self, s: CharacterSpec, u, *, blink: bool, mouth: str, tilt: float,
              head_cy: float = 48.0) -> Image.Image:
        """Head + hair on its own layer so it can tilt as a unit.

        The hair is a parametric dome (not a rounded rectangle, which read as a
        square head) and every translucent detail goes through `_overlay`.
        """
        S = SUPERSAMPLE
        layer = Image.new("RGBA", (int(BASE_W * S), int(BASE_H * S)), (0, 0, 0, 0))
        d = ImageDraw.Draw(layer)
        cx = BASE_W / 2
        hcy = head_cy
        head_r = 21.0

        def dome(radius: float, top: float, bottom: float, bulge: float = 0.0):
            """Smooth hair silhouette: dome on top, straight sides, soft bottom."""
            pts = []
            steps = 48
            for i in range(steps + 1):
                a = math.pi + math.pi * (i / steps)          # -180deg -> 0deg
                pts.append((cx + math.cos(a) * radius,
                            hcy + top + math.sin(a) * 0.0 + 0))
            # rebuild explicitly: arc across the top then down the sides
            pts = []
            for i in range(steps + 1):
                a = math.pi + math.pi * (i / steps)
                rr = radius * (1.0 + bulge * math.sin((i / steps) * math.pi))
                pts.append((cx + math.cos(a) * rr, hcy - 4.0 + math.sin(a) * rr))
            pts.append((cx + radius, hcy + bottom))
            pts.append((cx - radius, hcy + bottom))
            return pts

        # neck first (behind the head)
        d.rounded_rectangle((u(cx - 7.0), u(hcy + 14), u(cx + 7.0), u(hcy + 33)), radius=u(4.5),
                            fill=_rgba(_shine(s.skin, 0.88)))

        # back hair mass
        d.polygon([(u(x), u(y)) for x, y in dome(head_r + 5.5, -2.0, 16.0, 0.02)],
                  fill=_rgba(s.hair))
        d.rounded_rectangle((u(cx - head_r - 5.5), u(hcy + 6), u(cx + head_r + 5.5), u(hcy + 18)),
                            radius=u(7), fill=_rgba(s.hair))

        # ears: small, just outside the face
        for side in (-1, 1):
            ex = cx + side * (head_r + 0.6)
            d.ellipse((u(ex - 4.4), u(hcy + 3.0), u(ex + 4.4), u(hcy + 12.5)),
                      fill=_rgba(_shine(s.skin, 0.95)))

        # face
        d.ellipse((u(cx - head_r), u(hcy - head_r - 1), u(cx + head_r), u(hcy + head_r + 2)),
                  fill=_rgba(s.skin))

        # fringe: filled area above a wavy hairline
        pts = []
        steps = 26
        for i in range(steps + 1):
            t = i / steps
            a = math.pi + math.pi * t
            rr = head_r + 5.2
            pts.append((cx + math.cos(a) * rr, hcy - 4.0 + math.sin(a) * rr))
        for i in range(steps, -1, -1):
            t = i / steps
            x = cx - head_r - 4.0 + t * (head_r * 2 + 8)
            wave = math.sin(t * math.pi * 1.7 + 0.35) * 3.0
            y = hcy - head_r + 9.5 + wave + (1.0 - abs(t - 0.5) * 2) * 2.0
            pts.append((x, y))
        d.polygon([(u(x), u(y)) for x, y in pts], fill=_rgba(s.hair))

        # hair highlight: translucent band inside the fringe
        def _hair_light(dd, ox, oy):
            dd.arc((u(cx - head_r + 1) - ox, u(hcy - head_r - 6) - oy,
                    u(cx + head_r - 1) - ox, u(hcy + 12) - oy),
                   200, 320, fill=_rgba(s.hair_light, 165), width=int(2.6 * S))
        _overlay(layer, (u(cx - head_r + 1), u(hcy - head_r - 6),
                         u(cx + head_r - 1), u(hcy + 12)), _hair_light)

        # brows
        for side in (-1, 1):
            bx = cx + side * 9.0
            d.line([(u(bx - 5.0), u(hcy - 1.2)), (u(bx + 4.2), u(hcy - 3.4))],
                   fill=_rgba(s.hair, 235), width=int(2.0 * S))

        # eyes
        eye_y = hcy + 5.0
        for side in (-1, 1):
            ex = cx + side * 9.2
            if blink:
                d.arc((u(ex - 4.8), u(eye_y - 2.0), u(ex + 4.8), u(eye_y + 5.0)), 195, 345,
                      fill=_rgba(s.eye), width=int(1.8 * S))
            else:
                d.ellipse((u(ex - 4.4), u(eye_y - 6.0), u(ex + 4.4), u(eye_y + 5.2)),
                          fill=_rgba(s.eye))

        def _glints(dd, ox, oy):
            for side in (-1, 1):
                ex = cx + side * 9.2
                dd.ellipse((u(ex - 2.6) - ox, u(eye_y - 4.4) - oy,
                            u(ex + 0.1) - ox, u(eye_y - 1.5) - oy),
                           fill=(255, 255, 255, 238))
                dd.ellipse((u(ex + 1.2) - ox, u(eye_y + 1.4) - oy,
                            u(ex + 2.9) - ox, u(eye_y + 3.1) - oy),
                           fill=(255, 255, 255, 130))
        _overlay(layer, (u(cx - 16), u(eye_y - 6), u(cx + 16), u(eye_y + 6)), _glints)

        # blush: high on the cheeks, well clear of the mouth
        def _blush(dd, ox, oy):
            for side in (-1, 1):
                bx = cx + side * 14.4
                dd.ellipse((u(bx - 4.2) - ox, u(eye_y + 0.6) - oy,
                            u(bx + 4.2) - ox, u(eye_y + 5.2) - oy),
                           fill=_rgba(s.blush, 62))
        _overlay(layer, (u(cx - 20), u(eye_y), u(cx + 20), u(eye_y + 6)), _blush)

        # nose
        d.arc((u(cx - 2.2), u(hcy + 5.5), u(cx + 2.2), u(hcy + 10.0)), 15, 165,
              fill=_rgba(s.skin_shade), width=int(1.4 * S))

        # mouth
        my = hcy + 13.5
        if mouth == "open":
            d.ellipse((u(cx - 5.0), u(my - 2.8), u(cx + 5.0), u(my + 5.6)), fill=_rgba(s.line))
            d.ellipse((u(cx - 3.0), u(my + 0.8), u(cx + 3.0), u(my + 4.6)), fill=(150, 62, 74, 255))
        elif mouth == "flat":
            d.line([(u(cx - 4.0), u(my + 1.0)), (u(cx + 4.0), u(my + 1.0))],
                   fill=_rgba(s.line), width=int(1.9 * S))
        elif mouth == "o":
            d.ellipse((u(cx - 3.6), u(my - 1.6), u(cx + 3.6), u(my + 5.2)), fill=_rgba(s.line))
            d.ellipse((u(cx - 1.9), u(my + 0.6), u(cx + 1.9), u(my + 4.0)), fill=(150, 62, 74, 255))
        elif mouth == "small":
            d.arc((u(cx - 3.4), u(my - 1.2), u(cx + 3.4), u(my + 3.4)), 20, 160,
                  fill=_rgba(s.line), width=int(1.9 * S))
        else:  # smile
            d.arc((u(cx - 5.4), u(my - 3.0), u(cx + 5.4), u(my + 4.6)), 25, 155,
                  fill=_rgba(s.line), width=int(2.0 * S))
        return layer

    def _rotate(self, layer: Image.Image, degrees: float, head_cy: float = 48.0) -> Image.Image:
        if abs(degrees) < 0.05:
            return layer
        # rotate around the neck so the head pivots instead of sliding
        pivot = (BASE_W * SUPERSAMPLE / 2.0, (head_cy + 28.0) * SUPERSAMPLE)
        return layer.rotate(degrees, resample=Image.BICUBIC, center=pivot)

    def _arm(self, d, s: CharacterSpec, u, *, shoulder, angle: float, elbow: float,
             side: int, back: bool) -> None:
        """One arm: sleeve, upper arm, elbow, forearm, hand.

        `angle` swings the whole arm away from the body, `elbow` adds to the
        forearm angle (positive always bends further away from the body), so a
        small elbow reads as a relaxed arm and a large one as a folded gesture.
        """
        # mirror so a positive angle always swings away from the body on its own side
        angle = angle * side
        elbow = elbow * side
        upper, fore = 24.0, 22.0
        (ex, ey), (hx, hy) = _limb(shoulder, angle, elbow, upper, fore)

        dim = 0.94 if back else 1.0
        col_shirt = _rgba(_shine(s.shirt, 0.90 if back else 1.0))
        col_shirt_dark = _rgba(_shine(s.shirt_shade, 0.95 if back else 1.02))
        col_skin = _rgba(_shine(s.skin, dim))

        ux, uy = ex - shoulder[0], ey - shoulder[1]
        # ---- sleeve: ends past the halfway point of the upper arm
        sleeve = 0.90   # a T-shirt sleeve covers the whole upper arm
        mx, my = shoulder[0] + ux * sleeve, shoulder[1] + uy * sleeve
        _capsule(d, (u(shoulder[0]), u(shoulder[1])), (u(mx), u(my)),
                 u(11.8), col_shirt)
        # shoulder cap hides the joint seam where the sleeve meets the torso
        d.ellipse((u(shoulder[0] - 8.0), u(shoulder[1] - 8.0),
                   u(shoulder[0] + 8.0), u(shoulder[1] + 8.0)), fill=col_shirt)
        # cuff: a band at the sleeve end (a capsule with almost no length)
        c0 = (mx - ux * 0.02, my - uy * 0.02)
        c1 = (mx + ux * 0.05, my + uy * 0.05)
        _capsule(d, (u(c0[0]), u(c0[1])), (u(c1[0]), u(c1[1])), u(12.0), col_shirt_dark)

        # ---- upper arm, elbow, forearm: continuous taper, no joints bulging out
        d.ellipse((u(ex - 8.6), u(ey - 8.6), u(ex + 8.6), u(ey + 8.6)), fill=col_skin)
        wx_ = ex + (hx - ex) * 0.90
        wy_ = ey + (hy - ey) * 0.90
        _capsule(d, (u(ex), u(ey)), (u(wx_), u(wy_)), u(8.2), col_skin)
        # wrist narrows so the hand reads as a hand, not a stump
        w0x = ex + (hx - ex) * 0.74
        w0y = ey + (hy - ey) * 0.74
        _capsule(d, (u(w0x), u(w0y)), (u(wx_), u(wy_)), u(6.2), col_skin)

        # ---- hand: palm, thumb, and two soft finger bumps along the arm
        ang = math.atan2(hy - wy_, hx - wx_)
        r = 5.6
        d.ellipse((u(hx - r), u(hy - r), u(hx + r), u(hy + r)), fill=col_skin)
        t_ang = ang - 1.25 * side
        th = (hx + math.cos(t_ang) * 5.2, hy + math.sin(t_ang) * 5.2)
        d.ellipse((u(th[0] - 3.0), u(th[1] - 3.0), u(th[0] + 3.0), u(th[1] + 3.0)),
                  fill=col_skin)

    def _board(self, d, s: CharacterSpec, u, cx: float, sh_y: float) -> None:
        d.rounded_rectangle((u(cx - 34), u(sh_y + 12), u(cx - 6), u(sh_y + 40)), radius=u(3),
                            fill=_rgba(s.white))
        d.rounded_rectangle((u(cx - 32), u(sh_y + 14), u(cx - 8), u(sh_y + 38)), radius=u(2),
                            fill=_rgba(_shine(s.overalls, 1.25)))

    def _details(self, img: Image.Image, s: CharacterSpec, u, cx: float, sh_y: float,
                 hip_y: float) -> None:
        d = ImageDraw.Draw(img)
        # overall pocket + buttons (buttons are translucent, so overlay them)
        d.rounded_rectangle((u(cx - 8.0), u(sh_y + 26.0), u(cx + 8.0), u(sh_y + 37.0)), radius=u(3),
                            fill=_rgba(s.overalls_dark))

        def _buttons(dd, ox, oy):
            for sx in (cx - 11.5, cx + 11.5):
                dd.ellipse((u(sx - 2.0) - ox, u(sh_y + 17.0) - oy,
                            u(sx + 2.0) - ox, u(sh_y + 21.0) - oy),
                           fill=_rgba(s.accent, 230))
        _overlay(img, (u(cx - 15), u(sh_y + 15), u(cx + 15), u(sh_y + 23)), _buttons)

        def _soles(dd, ox, oy):
            for side in (-1, 1):
                bx = cx + side * 13.0
                dd.rounded_rectangle((u(bx - 10.0) - ox, u(FEET_Y - 4.0) - oy,
                                      u(bx + 10.0) - ox, u(FEET_Y) - oy),
                                     radius=u(2), fill=_rgba(s.line, 70))
        _overlay(img, (u(cx - 26), u(FEET_Y - 6), u(cx + 26), u(FEET_Y)), _soles)


CHARACTER = Character()


def available_poses():
    return sorted(POSES)
